import os
from taf.ul.ettf.msg_capture.comparison_table_generator import ComparisonTableGenerator
from taf.ul.ettf.utils.paths import logs_directory, unique_name, is_robot_context_available
from robot.api import logger as robot_writer
from taf.ul.ettf.logger import custom_logger


logger = custom_logger('ComparisonPresenter')


def write(content):
    robot_writer.write(content, level='HTML', html=True)


class ComparisonPresenter(object):
    def __init__(self):
        self.name = unique_name('matching_result')
        self.path = os.path.join(logs_directory(), '{}.{}'.format(self.name, 'html'))

    def show(self, comparison_history, history_type):
        html = ComparisonTableGenerator().generate_comparison_html(comparison_history, history_type, self.name, self.path)
        self._show_comparison_result_in_robot_log(html)
        logger.debug('Comparison result saved in file {}'.format(self.path))

    def _show_comparison_result_in_robot_log(self, html):
        if is_robot_context_available():
            write('Comparison result can also be found in {}'.format(self.path))
            write('<iframe seamless sandbox="allow-scripts" srcdoc="{}" width="100%" height="760px"></iframe>'.format(html))
            logger.debug('Comparison result added to log.html file')
        else:
            logger.debug('Robot context is not active, so comparison result will not be shown in robot log.html file')


class ExceptionlessComparisonPresenter(ComparisonPresenter):
    def show(self, comparison_history, comparison_container_type):
        try:
            super(ExceptionlessComparisonPresenter, self).show(comparison_history, comparison_container_type)
        except Exception as e:
            logger.warn(str(e))
            logger.warn('Error raised while generating comparison table!')
